function priceOrder(order, customer, promo) {
  const rate = { gold: 0.15, silver: 0.08, bronze: 0 }[customer.tier] ?? 0;
  let total = order.subtotal * (1 - rate);
  if (promo) total = total * (1 - promo.rate);
  return { total };
}

function makeInMemoryOrderRepo() {
  const store = {};
  return {
    saveOrder(orderId, total) { store[orderId] = total; },
    getOrder(orderId) { return store[orderId]; },
  };
}

function makeEventBus() {
  const subs = {};
  return {
    subscribe(topic, handler) {
      (subs[topic] = subs[topic] || []).push(handler);
    },
    publish(topic, payload) {
      (subs[topic] || []).forEach((h) => h(payload));
    },
  };
}

