function makeIdempotentHandler(fn) {
  const seen = new Set();
  return function (event) {
    if (seen.has(event.orderId)) return;
    seen.add(event.orderId);
    fn(event);
  };
}

function dedupeOrderIds(events) {
  const seen = new Set();
  const out = [];
  for (const e of events) {
    if (seen.has(e.orderId)) continue;
    seen.add(e.orderId);
    out.push(e);
  }
  return out;
}
